R.append(recipe('creme-abobora','Creme de abóbora com gengibre','entrada','Um começo de refeição cremoso, aromático e leve.',40,'Fácil',4,'🥣','photo-1547592180-85f173990554',[(650,'g','abóbora cabotiá sem casca'),(1,'un','cebola pequena'),(2,'dente','alho'),(1,'colher (sopa)','azeite'),(700,'ml','água ou caldo de legumes'),(1,'colher (chá)','gengibre ralado'),(.5,'colher (chá)','sal')],['Refogue cebola e alho no azeite até perfumar.','Junte abóbora em cubos, gengibre e caldo. Cozinhe tampado por cerca de 25 minutos.','Bata até ficar homogêneo, retorne à panela e ajuste sal e textura.','Sirva com azeite e sementes tostadas se desejar.'],'Comece com menos caldo e ajuste após bater.',['vegetariano','conforto']))
R.append(recipe('salada-grao-bico','Salada cítrica de grão-de-bico','entrada','Crocante e colorida, ótima para deixar pronta.',15,'Fácil',4,'🥗','photo-1512621776951-a57141f2eefd',[(400,'g','grão-de-bico cozido e escorrido'),(1,'un','pepino'),(2,'un','tomate'),(.5,'un','cebola roxa'),(1,'un','limão'),(2,'colher (sopa)','azeite'),(.5,'colher (chá)','sal'),(2,'colher (sopa)','salsinha')],['Corte pepino, tomate e cebola em cubos pequenos.','Misture ao grão-de-bico já frio.','Tempere com suco do limão, azeite, sal e salsinha.','Deixe 10 minutos na geladeira para integrar os sabores.'],'Se utilizar grão-de-bico de lata, lave e escorra bem.',['vegetariano','antecipar']))
R.append(recipe('caprese-palito','Espetinho caprese','entrada','Montagem simples com sabor de festa.',15,'Fácil',4,'🧀','photo-1608039829572-78524f79c4c7',[(16,'un','tomate-cereja'),(16,'un','bolinha de muçarela de búfala'),(16,'folha','manjericão'),(2,'colher (sopa)','azeite'),(1,'colher (sopa)','aceto balsâmico'),(.25,'colher (chá)','sal')],['Lave e seque bem os tomates e as folhas.','Monte os palitos alternando tomate, manjericão e queijo.','Disponha num prato e regue com azeite, balsâmico e uma pitada de sal.'],'Tempere apenas na hora de servir para preservar a apresentação.',['sem fogão','rápido']))
R.append(recipe('pao-alho-forno','Pão de alho caseiro','entrada','Cascas douradas e centro macio, ideal para compartilhar.',25,'Fácil',4,'🥖','photo-1619531040576-f9416740661e',[(4,'un','pão francês'),(70,'g','manteiga em temperatura ambiente'),(3,'dente','alho'),(2,'colher (sopa)','salsinha'),(40,'g','parmesão ralado'),(.25,'colher (chá)','sal')],['Misture manteiga, alho amassado, salsinha, queijo e sal.','Corte os pães sem separar as fatias até o fim.','Espalhe o creme entre os cortes e sobre os pães.','Leve ao forno a 200 °C por 12 a 15 minutos ou até dourar.'],'Vigie nos minutos finais para o alho não queimar.',['forno','para compartilhar']))
R.append(recipe('risoto-cogumelo','Risoto de cogumelos','principal','Arroz cremoso, cogumelos dourados e final de parmesão.',45,'Intermediário',3,'🍄','photo-1473093295043-cdd812d0e601',[(240,'g','arroz arbóreo'),(250,'g','cogumelos frescos'),(1,'un','cebola pequena'),(1,'colher (sopa)','azeite'),(25,'g','manteiga'),(75,'g','parmesão'),(900,'ml','caldo de legumes quente'),(.5,'colher (chá)','sal')],['Mantenha o caldo aquecido em uma panela.','Doure os cogumelos fatiados em metade do azeite e reserve.','Refogue a cebola no restante do azeite, junte o arroz e mexa por 1 minuto.','Adicione caldo aos poucos, mexendo frequentemente até o arroz ficar al dente (aproximadamente 18–22 minutos).','Misture cogumelos, manteiga e parmesão, ajuste o sal e sirva imediatamente.'],'O caldo deve estar quente; ajuste a quantidade ao ponto do arroz.',['italiano','vegetariano']))
R.append(recipe('frango-limao','Frango assado com limão e ervas','principal','Frango suculento com bordas douradas e ervas.',65,'Fácil',4,'🍗','photo-1532550907401-a500c9a57435',[(850,'g','sobrecoxa de frango'),(1,'un','limão'),(3,'dente','alho'),(2,'colher (sopa)','azeite'),(1,'colher (chá)','páprica'),(1,'colher (chá)','sal'),(2,'ramo','alecrim')],['Aqueça o forno a 210 °C.','Tempere as sobrecoxas com limão, alho, azeite, páprica, sal e alecrim.','Espalhe numa assadeira sem sobrepor as peças.','Asse por 40 a 50 minutos, até dourar e atingir ao menos 74 °C no centro.','Deixe descansar por 5 minutos antes de servir.'],'Termômetro culinário é a forma mais segura de confirmar o ponto do frango.',['forno','proteína']))
R.append(recipe('massa-tomate','Massa ao molho de tomate assado','principal','Molho intenso e adocicado feito praticamente sozinho.',50,'Fácil',4,'🍝','photo-1473093295043-cdd812d0e601',[(350,'g','massa seca'),(650,'g','tomate maduro'),(1,'un','cebola roxa'),(4,'dente','alho'),(3,'colher (sopa)','azeite'),(1,'colher (chá)','sal'),(10,'folha','manjericão')],['Aqueça o forno a 210 °C e espalhe tomates, cebola e alho na assadeira.','Tempere com azeite e sal e asse por 30 minutos.','Cozinhe a massa em água salgada até ficar al dente, reservando um pouco da água.','Amasse ou bata os vegetais assados, misture à massa e ajuste com a água reservada.','Finalize com manjericão.'],'Guarde meia xícara da água do cozimento para emulsionar o molho.',['italiano','forno']))
