R.append(recipe('omelete-espinafre','Omelete de espinafre e queijo','principal','Refeição de frigideira rápida e versátil.',18,'Fácil',2,'🍳','photo-1525351484163-7529414344d8',[(4,'un','ovo'),(70,'g','espinafre'),(60,'g','queijo minas'),(1,'colher (sopa)','azeite'),(.25,'colher (chá)','sal')],['Bata os ovos com uma pitada de sal.','Aqueça o azeite e murche o espinafre por 1 a 2 minutos.','Despeje os ovos e distribua o queijo em cubinhos.','Cozinhe em fogo baixo até firmar; dobre e finalize até o centro estar cozido.'],'Fogo moderado evita omelete ressecada por fora e crua por dentro.',['rápido','vegetariano']))
R.append(recipe('brownie-chocolate','Brownie de chocolate intenso','sobremesa','Casquinha fina e interior úmido, sem exageros.',40,'Fácil',9,'🍫','photo-1606313564200-e75d5e30476c',[(170,'g','chocolate meio amargo'),(120,'g','manteiga'),(160,'g','açúcar'),(2,'un','ovo'),(85,'g','farinha de trigo'),(20,'g','cacau em pó'),(.25,'colher (chá)','sal')],['Preaqueça o forno a 180 °C e forre uma forma pequena (aprox. 20 × 20 cm).','Derreta chocolate e manteiga e espere amornar.','Misture açúcar e ovos, acrescente o chocolate e depois os ingredientes secos.','Espalhe na forma e asse 20 a 26 minutos; o centro deve estar úmido, não líquido.','Espere esfriar antes de cortar.'],'Não asse até o palito sair completamente seco: isso resseca o brownie.',['chocolate','forno']))
